 kcms/notifications/ui/main.qml                | 34 +++++++++++++++++++
 .../abstractnotificationsmodel.cpp            |  6 +++-
 .../abstractnotificationsmodel.h              |  2 +-
 libnotificationmanager/jobsmodel.cpp          |  6 +++-
 libnotificationmanager/jobsmodel.h            |  3 +-
 .../kcfg/notificationsettings.kcfg            |  3 ++
 libnotificationmanager/notifications.cpp      | 13 +++++++
 libnotificationmanager/notifications.h        |  9 +++++
 libnotificationmanager/settings.cpp           | 14 ++++++++
 libnotificationmanager/settings.h             |  7 ++++
 11 files changed, 104 insertions(+), 5 deletions(-)

diff --git a/applets/notifications/global/Globals.qml b/applets/notifications/global/Globals.qml
index 8e8e56f88d..57e3a7da73 100644
--- a/applets/notifications/global/Globals.qml
+++ b/applets/notifications/global/Globals.qml
@@ -272,6 +272,13 @@ QtObject {
         globals.plasmoid = globals.plasmoidItem.plasmoid;
     }

+    function clearOldHistory(): void {
+        const timeout = notificationSettings.historyTimeout;
+        if (timeout > 0) {
+            popupNotificationsModel.clearOlderThan(NotificationManager.Notifications.ClearExpired, new Date(Date.now() - timeout * 60 * 1000));
+        }
+    }
+
     function checkInhibition() {
         globals.inhibited = Qt.binding(function() {
             var inhibited = false;
@@ -464,6 +471,7 @@ QtObject {

     property NotificationManager.Settings notificationSettings: NotificationManager.Settings {
         onNotificationsInhibitedUntilChanged: globals.checkInhibition()
+        onSettingsChanged: globals.clearOldHistory()
     }

     property TaskManager.TasksModel tasksModel: TaskManager.TasksModel {
@@ -471,10 +479,12 @@ QtObject {
         groupInline: false
     }

-    // This periodically checks whether do not disturb mode timed out and updates the "minutes ago" labels
+    // This periodically checks whether do not disturb mode timed out, removes old notifications from the history
+    // and updates the "minutes ago" labels
     property Clock clockSource: Clock {
         onDateTimeChanged: {
             globals.checkInhibition();
+            globals.clearOldHistory();
             globals.timeChanged();
         }
     }
diff --git a/kcms/notifications/ui/main.qml b/kcms/notifications/ui/main.qml
index 83dc77275c..d5f0866dc9 100644
--- a/kcms/notifications/ui/main.qml
+++ b/kcms/notifications/ui/main.qml
@@ -216,6 +216,40 @@ KCM.SimpleKCM {
             }
         }

+        QtControls.ComboBox {
+            id: historyTimeoutCombo
+            Kirigami.FormData.label: i18nc("@label:listbox", "Remove from history:")
+            textRole: "text"
+            valueRole: "value"
+            model: [
+                { text: i18nc("@item:inlistbox Remove notifications from history", "Never"), value: 0 },
+                { text: i18nc("@item:inlistbox Remove notifications from history", "After 1 hour"), value: 60 },
+                { text: i18nc("@item:inlistbox Remove notifications from history", "After 1 day"), value: 60 * 24 },
+                { text: i18nc("@item:inlistbox Remove notifications from history", "After 1 week"), value: 60 * 24 * 7 },
+            ]
+            onActivated: kcm.notificationSettings.historyTimeout = currentValue
+
+            Component.onCompleted: selectCurrent()
+
+            Connections {
+                target: kcm.notificationSettings
+
+                function onHistoryTimeoutChanged(): void {
+                    historyTimeoutCombo.selectCurrent()
+                }
+            }
+
+            function selectCurrent(): void {
+                currentIndex = indexOfValue(kcm.notificationSettings.historyTimeout);
+            }
+
+            KCM.SettingStateBinding {
+                configObject: kcm.notificationSettings
+                settingName: "HistoryTimeout"
+                extraEnabledConditions: root.notificationsAvailable
+            }
+        }
+
         QtControls.ButtonGroup {
             id: positionGroup
             buttons: [positionCloseToWidget, positionCustomPosition]
