+void Notifications::clearOlderThan(ClearFlags flags, const QDateTime &dateTime)
+{
+    if (d->notificationsModel) {
+        d->notificationsModel->clear(flags, dateTime);
+    }
+    if (d->portalNotificationsModel) {
+        d->portalNotificationsModel->clear(flags, dateTime);
+    }
+    if (d->jobsModel) {
+        d->jobsModel->clear(flags, dateTime);
+    }
+}
