     Q_INVOKABLE void clear(ClearFlags flags);

+    /**
+     * @brief Clear notifications older than a given date
+     *
+     * Like @c clear but only removes notifications that were last updated before @p dateTime.
+     * This can be used for e.g. removing old notifications from the history automatically.
+     * @since 6.9
+     */
