      */
diff --git a/libnotificationmanager/settings.cpp b/libnotificationmanager/settings.cpp
index 9e0da288ab..c669a9f11d 100644
--- a/libnotificationmanager/settings.cpp
+++ b/libnotificationmanager/settings.cpp
@@ -395,6 +395,20 @@ void Settings::setLowPriorityHistory(bool enable)
     d->setDirty(true);
 }

+int Settings::historyTimeout() const
+{
+    return d->notificationSettings.historyTimeout();
+}
+
+void Settings::setHistoryTimeout(int timeout)
+{
+    if (this->historyTimeout() == timeout) {
+        return;
+    }
+    d->notificationSettings.setHistoryTimeout(timeout);
+    d->setDirty(true);
+}
+
 Settings::PopupPosition Settings::popupPosition() const
 {
     return static_cast<Settings::PopupPosition>(d->notificationSettings.popupPosition());
